scripts.script:
const TextChatService = game:FindService("TextChatService") :: TextChatService;
const RunService = game:FindService("RunService") :: RunService;
const BCConfig = TextChatService:FindFirstChild("BubbleChatConfiguration") :: BubbleChatConfiguration;
-- const CWConfig = TextChatService:FindFirstChild("ChatWindowConfiguration") :: ChatWindowConfiguration;

const fromRGB: (number?, number?, number?) -> Color3 = Color3.fromRGB;
const fromHSV:(number, number, number) -> Color3 = Color3.fromHSV
const Vec3New:(number?, number?, number?) -> Vector3 = Vector3.new;

if getgenv().__Conn then
    getgenv().__Conn:Disconnect();
end

getgenv().__Conn = RunService.PreRender:Connect(function()
    BCConfig.TextColor3 = fromHSV((tick() * 0.35) % 1.00000000000000000000000000000000000000000000000000000001, .79, .95);
    BCConfig.BackgroundColor3 = fromRGB(22, 22, 28)
    BCConfig.LocalPlayerStudsOffset = Vec3New(0, 0.2, 0);
    BCConfig.MaxDistance = 300;
end)
